	    SalesCampaign parentEntity = repository.findById(parentId).get();
	    Quote child = registry.project( Quote.class, removeFrom.getQuoteId());
	    
	    parentEntity.getQuotes().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
